use axum::{
    extract::{Json, Path, Query, State},
    http::StatusCode,
};
use chrono::Utc;
use loco_rs::prelude::*;
use serde::Deserialize;
use serde_json::{json, Value};

use crate::{
    controllers::api::{self, ApiError, ApiResult, OptionalViewer, Viewer},
    models::{articles, favorites, users},
    views::realworld::ArticleView,
};

#[derive(Default, Deserialize)]
pub struct ListQuery {
    tag: Option<String>,
    author: Option<String>,
    favorited: Option<String>,
    limit: Option<usize>,
    offset: Option<usize>,
}

#[derive(Deserialize)]
struct Envelope<T> {
    article: T,
}

#[derive(Deserialize)]
struct NewArticle {
    #[serde(default)]
    title: String,
    #[serde(default)]
    description: String,
    #[serde(default)]
    body: String,
    #[serde(default, rename = "tagList")]
    tag_list: Vec<String>,
    #[serde(default = "published_status")]
    status: Value,
}

fn published_status() -> Value {
    json!("published")
}

fn visible(
    article: Option<articles::Model>,
    viewer_id: Option<i64>,
) -> std::result::Result<articles::Model, ApiError> {
    let article = article.ok_or(ApiError::missing("article"))?;
    if article.is_draft() && Some(article.author_id) != viewer_id {
        return Err(ApiError::missing("article"));
    }
    Ok(article)
}

fn owned(
    article: articles::Model,
    viewer_id: i64,
) -> std::result::Result<articles::Model, ApiError> {
    if article.author_id != viewer_id {
        return Err(ApiError::forbidden("article"));
    }
    Ok(article)
}

pub async fn find(
    ctx: &AppContext,
    slug: &str,
    viewer_id: Option<i64>,
) -> std::result::Result<articles::Model, ApiError> {
    visible(articles::Model::by_slug(&ctx.db, slug).await?, viewer_id)
}

pub fn interactable(article: &articles::Model) -> std::result::Result<(), ApiError> {
    if article.is_draft() {
        Err(ApiError::new(
            StatusCode::UNPROCESSABLE_ENTITY,
            "article",
            "is a draft",
        ))
    } else {
        Ok(())
    }
}

async fn single(
    ctx: &AppContext,
    article: &articles::Model,
    viewer: Option<&users::Model>,
    status: StatusCode,
) -> ApiResult {
    let article = ArticleView::load(&ctx.db, article, viewer, true).await?;
    Ok(api::json_response(status, json!({"article": article})))
}

async fn list_response(
    ctx: &AppContext,
    viewer: Option<&users::Model>,
    query: ListQuery,
    feed: bool,
) -> ApiResult {
    let author = if let Some(name) = query.author.as_deref() {
        match users::Model::by_username(&ctx.db, name).await? {
            Some(user) => Some(user.id),
            None => {
                return Ok(api::json_response(
                    StatusCode::OK,
                    json!({"articles": [], "articlesCount": 0}),
                ))
            }
        }
    } else {
        None
    };
    let favorited = if let Some(name) = query.favorited.as_deref() {
        match users::Model::by_username(&ctx.db, name).await? {
            Some(user) => Some(user.id),
            None => {
                return Ok(api::json_response(
                    StatusCode::OK,
                    json!({"articles": [], "articlesCount": 0}),
                ))
            }
        }
    } else {
        None
    };
    let (articles, count) = articles::Model::list(
        &ctx.db,
        author,
        favorited,
        query.tag.as_deref(),
        if feed { viewer.map(|u| u.id) } else { None },
        query.limit.unwrap_or(20),
        query.offset.unwrap_or(0),
    )
    .await?;
    many(ctx, &articles, count, viewer).await
}

async fn many(
    ctx: &AppContext,
    articles: &[articles::Model],
    count: usize,
    viewer: Option<&users::Model>,
) -> ApiResult {
    let mut views = Vec::new();
    for article in articles {
        views.push(ArticleView::load(&ctx.db, article, viewer, false).await?);
    }
    Ok(api::json_response(
        StatusCode::OK,
        json!({"articles": views, "articlesCount": count}),
    ))
}

#[debug_handler]
async fn list(
    OptionalViewer(viewer): OptionalViewer,
    State(ctx): State<AppContext>,
    Query(query): Query<ListQuery>,
) -> ApiResult {
    list_response(&ctx, viewer.as_ref(), query, false).await
}

#[debug_handler]
async fn feed(
    Viewer(viewer): Viewer,
    State(ctx): State<AppContext>,
    Query(query): Query<ListQuery>,
) -> ApiResult {
    list_response(&ctx, Some(&viewer), query, true).await
}

#[debug_handler]
async fn drafts(
    Viewer(viewer): Viewer,
    State(ctx): State<AppContext>,
    Query(query): Query<ListQuery>,
) -> ApiResult {
    let (articles, count) = articles::Model::drafts(
        &ctx.db,
        viewer.id,
        query.limit.unwrap_or(20),
        query.offset.unwrap_or(0),
    )
    .await?;
    many(&ctx, &articles, count, Some(&viewer)).await
}

#[debug_handler]
async fn show(
    Path(slug): Path<String>,
    OptionalViewer(viewer): OptionalViewer,
    State(ctx): State<AppContext>,
) -> ApiResult {
    let article = find(&ctx, &slug, viewer.as_ref().map(|user| user.id)).await?;
    single(&ctx, &article, viewer.as_ref(), StatusCode::OK).await
}

#[debug_handler]
async fn create(
    Viewer(viewer): Viewer,
    State(ctx): State<AppContext>,
    Json(Envelope { article }): Json<Envelope<NewArticle>>,
) -> ApiResult {
    api::required(&article.title, "title")?;
    api::required(&article.description, "description")?;
    api::required(&article.body, "body")?;
    let status = match article.status.as_str() {
        Some("draft") => "draft",
        Some("published") => "published",
        _ => return Err(ApiError::invalid("status")),
    };
    let article = articles::Model::create(
        &ctx.db,
        viewer.id,
        article.title,
        article.description,
        article.body,
        article.tag_list,
        status.to_owned(),
    )
    .await?;
    single(&ctx, &article, Some(&viewer), StatusCode::CREATED).await
}

fn changed_text(
    changes: &Value,
    field: &'static str,
) -> std::result::Result<Option<String>, ApiError> {
    changes
        .get(field)
        .map(|value| {
            let text = value.as_str().ok_or(ApiError::blank(field))?;
            api::required(text, field)?;
            Ok(text.to_owned())
        })
        .transpose()
}

#[debug_handler]
async fn update(
    Path(slug): Path<String>,
    Viewer(viewer): Viewer,
    State(ctx): State<AppContext>,
    Json(Envelope { article: changes }): Json<Envelope<Value>>,
) -> ApiResult {
    let txn = ctx.db.begin().await?;
    let article = owned(
        visible(
            articles::Model::by_slug_for_update(&txn, &slug).await?,
            Some(viewer.id),
        )?,
        viewer.id,
    )?;
    if let Some(revision) = changes.get("revision") {
        if !revision.is_i64() && !revision.is_u64() {
            return Err(ApiError::invalid("revision"));
        }
        if *revision != json!(article.revision) {
            let current = ArticleView::load(&ctx.db, &article, Some(&viewer), true).await?;
            return Ok(api::json_response(
                StatusCode::CONFLICT,
                json!({"errors": {"revision": ["is stale"]}, "article": current}),
            ));
        }
    }
    let mut active = article.revised();
    if let Some(title) = changed_text(&changes, "title")? {
        active.slug = Set(articles::Model::slug_for(&title));
        active.title = Set(title);
    }
    if let Some(description) = changed_text(&changes, "description")? {
        active.description = Set(description);
    }
    if let Some(body) = changed_text(&changes, "body")? {
        active.body = Set(body);
    }
    if let Some(tags) = changes.get("tagList") {
        let tags: Vec<String> =
            serde_json::from_value(tags.clone()).map_err(|_| ApiError::invalid("tagList"))?;
        active = active.replace_tags(tags);
    }
    let article = active.update(&txn).await?;
    txn.commit().await?;
    single(&ctx, &article, Some(&viewer), StatusCode::OK).await
}

#[debug_handler]
async fn remove(
    Path(slug): Path<String>,
    Viewer(viewer): Viewer,
    State(ctx): State<AppContext>,
) -> ApiResult {
    let article = owned(find(&ctx, &slug, Some(viewer.id)).await?, viewer.id)?;
    article.delete(&ctx.db).await?;
    Ok(StatusCode::NO_CONTENT.into_response())
}

#[debug_handler]
async fn publish(
    Path(slug): Path<String>,
    Viewer(viewer): Viewer,
    State(ctx): State<AppContext>,
) -> ApiResult {
    let txn = ctx.db.begin().await?;
    let article = owned(
        visible(
            articles::Model::by_slug_for_update(&txn, &slug).await?,
            Some(viewer.id),
        )?,
        viewer.id,
    )?;
    if !article.is_draft() {
        txn.commit().await?;
        return single(&ctx, &article, Some(&viewer), StatusCode::OK).await;

use std::collections::BTreeSet;

use chrono::Utc;
use loco_rs::prelude::*;
use sea_orm::{DatabaseTransaction, Select};
use serde_json::Value;
use uuid::Uuid;

pub use super::_entities::articles::{self, ActiveModel, Entity, Model};

#[async_trait::async_trait]
impl ActiveModelBehavior for ActiveModel {
    async fn before_save<C>(mut self, _db: &C, insert: bool) -> std::result::Result<Self, DbErr>
    where
        C: ConnectionTrait,
    {
        if !insert {
            self.updated_at = Set(Utc::now().into());
        }
        Ok(self)
    }
}

impl Model {
    fn with_slug(slug: &str) -> Select<Entity> {
        Entity::find().filter(articles::Column::Slug.eq(slug))
    }

    fn published() -> Select<Entity> {
        Entity::find().filter(articles::Column::Status.eq("published"))
    }

    pub async fn by_slug<C: ConnectionTrait>(
        db: &C,
        slug: &str,
    ) -> std::result::Result<Option<Self>, DbErr> {
        Self::with_slug(slug).one(db).await
    }

    pub async fn by_slug_for_update(
        db: &DatabaseTransaction,
        slug: &str,
    ) -> std::result::Result<Option<Self>, DbErr> {
        Self::with_slug(slug).lock_exclusive().one(db).await
    }

    pub async fn create(
        db: &DatabaseConnection,
        author_id: i64,
        title: String,
        description: String,
        body: String,
        tags: Vec<String>,
        status: String,
    ) -> std::result::Result<Self, DbErr> {
        let published_at = (status == "published").then(|| Utc::now().into());
        ActiveModel {
            slug: Set(Self::slug_for(&title)),
            title: Set(title),
            description: Set(description),
            body: Set(body),
            tag_list: Set(serde_json::json!(tags)),
            author_id: Set(author_id),
            status: Set(status),
            published_at: Set(published_at),
            ..Default::default()
        }
        .insert(db)
        .await
    }

    pub fn tags(&self) -> Vec<String> {
        serde_json::from_value(self.tag_list.clone()).unwrap_or_default()
    }

    pub fn is_draft(&self) -> bool {
        self.status == "draft"
    }

    pub fn revised(&self) -> ActiveModel {
        let mut active = self.clone().into_active_model();
        active.revision = Set(self.revision + 1);
        active
    }

    pub fn slug_for(title: &str) -> String {
        format!("{}-{}", slug::slugify(title), Uuid::new_v4().simple())
    }

    pub async fn list(
        db: &DatabaseConnection,
        author: Option<i64>,
        favorited: Option<i64>,
        tag: Option<&str>,
        feed: Option<i64>,
        limit: usize,
        offset: usize,
    ) -> std::result::Result<(Vec<Self>, usize), DbErr> {
        use super::favorites;
        use super::follows;
        let mut query = Self::published().order_by_desc(articles::Column::Id);
        if let Some(author) = author {
            query = query.filter(articles::Column::AuthorId.eq(author));
        }
        if let Some(user_id) = favorited {
            let ids: Vec<i64> = favorites::Entity::find()
                .filter(favorites::Column::UserId.eq(user_id))
                .all(db)
                .await?
                .into_iter()
                .map(|f| f.article_id)
                .collect();
            if ids.is_empty() {
                return Ok((Vec::new(), 0));
            }
            query = query.filter(articles::Column::Id.is_in(ids));
        }
        if let Some(user_id) = feed {
            let ids: Vec<i64> = follows::Entity::find()
                .filter(follows::Column::FollowerId.eq(user_id))
                .all(db)
                .await?
                .into_iter()
                .map(|f| f.followed_id)
                .collect();
            if ids.is_empty() {
                return Ok((Vec::new(), 0));
            }
            query = query.filter(articles::Column::AuthorId.is_in(ids));
        }
        if let Some(tag) = tag {
            let mut articles = query.all(db).await?;
            articles.retain(|article| article.tags().iter().any(|item| item == tag));
            let count = articles.len();
            return Ok((
                articles.into_iter().skip(offset).take(limit).collect(),
                count,
            ));
        }
        let count = query.clone().count(db).await? as usize;
        let articles = query
            .offset(offset as u64)
            .limit(limit as u64)
            .all(db)
            .await?;
        Ok((articles, count))
    }

    pub async fn drafts(
        db: &DatabaseConnection,
        author_id: i64,
        limit: usize,
        offset: usize,
    ) -> std::result::Result<(Vec<Self>, usize), DbErr> {
        let query = Entity::find()
            .filter(articles::Column::AuthorId.eq(author_id))
            .filter(articles::Column::Status.eq("draft"))
            .order_by_desc(articles::Column::Id);
        let count = query.clone().count(db).await? as usize;
        let articles = query
            .offset(offset as u64)
            .limit(limit as u64)
            .all(db)
            .await?;
        Ok((articles, count))
    }

    pub async fn all_tags(db: &DatabaseConnection) -> std::result::Result<BTreeSet<String>, DbErr> {
        Ok(Self::published()
            .all(db)
            .await?
            .iter()
            .flat_map(Self::tags)
            .collect())
    }
}

impl ActiveModel {
    pub fn replace_tags(mut self, tags: Vec<String>) -> Self {
        self.tag_list = Set(Value::from(tags));
        self
    }
}

use loco_rs::prelude::*;
use serde::Serialize;

use crate::models::{articles, comments, favorites, follows, users};

#[derive(Serialize)]
pub struct UserView {
    pub email: String,
    pub token: String,
    pub username: String,
    pub bio: Option<String>,
    pub image: Option<String>,
}

impl UserView {
    pub fn new(user: &users::Model, token: String) -> Self {
        Self {
            email: user.email.clone(),
            token,
            username: user.username.clone(),
            bio: user.bio.clone(),
            image: user.image.clone(),
        }
    }
}

#[derive(Serialize)]
pub struct ProfileView {
    pub username: String,
    pub bio: Option<String>,
    pub image: Option<String>,
    pub following: bool,
}

impl ProfileView {
    pub async fn load(
        db: &DatabaseConnection,
        user: &users::Model,
        viewer: Option<&users::Model>,
    ) -> std::result::Result<Self, DbErr> {
        let following = if let Some(viewer) = viewer {
            follows::Model::is_following(db, viewer.id, user.id).await?
        } else {
            false
        };
        Ok(Self {
            username: user.username.clone(),
            bio: user.bio.clone(),
            image: user.image.clone(),
            following,
        })
    }
}

#[derive(Serialize)]
#[serde(rename_all = "camelCase")]
pub struct ArticleView {
    pub slug: String,
    pub title: String,
    pub description: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub body: Option<String>,
    pub tag_list: Vec<String>,
    pub created_at: String,
    pub updated_at: String,
    pub status: String,
    pub published_at: Option<String>,
    pub revision: i32,
    pub favorited: bool,
    pub favorites_count: u64,
    pub author: ProfileView,
}

impl ArticleView {
    pub async fn load(
        db: &DatabaseConnection,
        article: &articles::Model,
        viewer: Option<&users::Model>,
        include_body: bool,
    ) -> std::result::Result<Self, DbErr> {
        let author = users::Entity::find_by_id(article.author_id)
            .one(db)
            .await?
            .ok_or(DbErr::RecordNotFound("author".into()))?;
        let favorited = if let Some(viewer) = viewer {
            favorites::Model::is_favorited(db, viewer.id, article.id).await?
        } else {
            false
        };
        Ok(Self {
            slug: article.slug.clone(),
            title: article.title.clone(),
            description: article.description.clone(),
            body: include_body.then(|| article.body.clone()),
            tag_list: article.tags(),
            created_at: article.created_at.to_rfc3339(),
            updated_at: article.updated_at.to_rfc3339(),
            status: article.status.clone(),
            published_at: article.published_at.map(|time| time.to_rfc3339()),
            revision: article.revision,
            favorited,
            favorites_count: favorites::Model::count(db, article.id).await?,
            author: ProfileView::load(db, &author, viewer).await?,
        })
    }
}

#[derive(Serialize)]
#[serde(rename_all = "camelCase")]
pub struct CommentView {
    pub id: i64,
    pub created_at: String,
    pub updated_at: String,
    pub body: String,
    pub author: ProfileView,
}

impl CommentView {
    pub async fn load(
        db: &DatabaseConnection,
        comment: &comments::Model,
        viewer: Option<&users::Model>,
    ) -> std::result::Result<Self, DbErr> {
        let author = users::Entity::find_by_id(comment.author_id)
            .one(db)
            .await?
            .ok_or(DbErr::RecordNotFound("author".into()))?;
        Ok(Self {
            id: comment.id,
            created_at: comment.created_at.to_rfc3339(),
            updated_at: comment.updated_at.to_rfc3339(),
            body: comment.body.clone(),
            author: ProfileView::load(db, &author, viewer).await?,
        })
    }
}

